package com.ekayn.api.api; import com.ekayn.api.api.ApiModels.*; import com.ekayn.api.model.*; import com.ekayn.api.service.OrderService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/orders") @RequiredArgsConstructor public class OrderController { private final OrderService service; @GetMapping public List<OrderSummaryResponse> mine(@AuthenticationPrincipal User u){return service.mine(u);} @GetMapping("/{id}") public OrderDetailResponse one(@AuthenticationPrincipal User u,@PathVariable UUID id){return service.mineOne(u,id);} }
